(7532270, 1204310, 50641, '<td valign="top">blue</td>', 'blue', '2017-09-01 01:07:25.000000', NULL, 1),
(7532333, 1204832, 1647, '<td valign="top">Great picture - I really like the crashing water, and I know you must have pushed the image around a lot to deal with the shadows and contrast.  I think it could have been a tiny bit darker - but I''d need to see it to decide.</td>', 'Great picture - I really like the crashing water, and I know you must have pushed the image around a lot to deal with the shadows and contrast.  I think it could have been a tiny bit darker - but I''d need to see it to decide.', '2017-09-01 04:29:38.000000', NULL, 1),
(7532334, 1204863, 1647, '<td valign="top">I love all of the facial expressions - it''s a shame the people aren''t sharper.  Did you deliberately blur it to try and capture motion or unintentional?  I think a bit sharper would have been better.</td>', 'I love all of the facial expressions - it''s a shame the people aren''t sharper.  Did you deliberately blur it to try and capture motion or unintentional?  I think a bit sharper would have been better.', '2017-09-01 04:30:52.000000', NULL, 1),
(7532335, 1204912, 1647, '<td valign="top">It''s nicely focussed, and the combination of the boy and the boat in the background is great.  Perhaps could have been lightened a little more to try and get the boy to "normal" exposure - he''s just a bit dark.</td>', 'It''s nicely focussed, and the combination of the boy and the boat in the background is great.  Perhaps could have been lightened a little more to try and get the boy to "normal" exposure - he''s just a bit dark.', '2017-09-01 04:32:46.000000', NULL, 1),
(7532337, 1204858, 1647, '<td valign="top">Great pic - the child is so small that they are almost missed at first.  Title works great.  Did you happen to take any closer pics, from the child''s height of the imposing climb that it must be?</td>', 'Great pic - the child is so small that they are almost missed at first.  Title works great.  Did you happen to take any closer pics, from the child''s height of the imposing climb that it must be?', '2017-09-01 04:35:21.000000', NULL, 1),
(7532338, 1204958, 1647, '<td valign="top">An interesting choice of colour treatment for a picture of two cats - certainly turns it towards artistic in its interpretation.  If the cat with it''s head at the bottom was positioned more like the top cat (Don''t worry - I''m not actually telling you to arrange the cat, just wishing) it would have been even better</td>', 'An interesting choice of colour treatment for a picture of two cats - certainly turns it towards artistic in its interpretation.  If the cat with it''s head at the bottom was positioned more like the top cat (Don''t worry - I''m not actually telling you to arrange the cat, just wishing) it would have been even better', '2017-09-01 04:37:36.000000', NULL, 1),
(7532339, 1204910, 1647, '<td valign="top">Great expressions and a great moment captured - a picture to be treasured.  Exposure and colour treatment looks great to me.  Perhaps would have been nice to see more of the baby, but still a great photo</td>', 'Great expressions and a great moment captured - a picture to be treasured.  Exposure and colour treatment looks great to me.  Perhaps would have been nice to see more of the baby, but still a great photo', '2017-09-01 04:38:54.000000', NULL, 1),
