(7533315, 1204963, 83313, '<td valign="top">Interesting use of a "texture". I like it.</td>', 'Interesting use of a "texture". I like it.', '2017-09-05 21:56:42.000000', NULL, 1),
(7533316, 1204706, 16148, '<td valign="top">Interesting composition with brilliant textures.</td>', 'Interesting composition with brilliant textures.', '2017-09-05 21:58:20.000000', NULL, 1),
(7533317, 1204904, 16148, '<td valign="top">Beautiful candid.  The square crop worked well.</td>', 'Beautiful candid.  The square crop worked well.', '2017-09-05 22:01:16.000000', NULL, 1),
