(7533438, 1204858, 114285, '<td valign="top">Cute moment, hope he made it without falling!</td>', 'Cute moment, hope he made it without falling!', '2017-09-06 11:04:37.000000', NULL, 1),
(7533440, 1204779, 114285, '<td valign="top">Paul?? Love how the legs look tiny on the big body.</td>', 'Paul?? Love how the legs look tiny on the big body.', '2017-09-06 11:08:06.000000', NULL, 1),
(7533441, 1204663, 114285, '<td valign="top">Great lighting and all, but why is the dog looking away?  Extra points if it was looking at you ;)</td>', 'Great lighting and all, but why is the dog looking away?  Extra points if it was looking at you ;)', '2017-09-06 11:09:58.000000', NULL, 1),
(7533442, 1204883, 114285, '<td valign="top">Shows you God has a sense of humour, you see it often in his creation...look at all the funny faces, I see three of them. Great  find!</td>', 'Shows you God has a sense of humour, you see it often in his creation...look at all the funny faces, I see three of them. Great  find!', '2017-09-06 11:12:22.000000', NULL, 1),
(7533487, 1204715, 173844, '<td valign="top">Truly beautiful image of this giraffe in its environment.  The black and white treatment, especially as it''s handled here, engenders a distance, a remove, from the here and now.  Which, in my opinion, mingles nostalgia with sadness.  Perhaps I''m projecting due to knowledge of their current precarious situation across Africa.  I like the white sky, which leaves the focus clearly on the foreground.  As to the rather light hindquarters, I''m torn as to whether it really helps the image; if that''s not a result of aesthetic processing choice, then please excuse my presumptuousness.  It certainly helps in bringing it forward, distinguished from the brush.  The delicacy and empathy here are remarkable.<br/>My personal favorite in the challenge.</td>', 'Truly beautiful image of this giraffe in its environment.  The black and white treatment, especially as it''s handled here, engenders a distance, a remove, from the here and now.  Which, in my opinion, mingles nostalgia with sadness.  Perhaps I''m projecting due to knowledge of their current precarious situation across Africa.  I like the white sky, which leaves the focus clearly on the foreground.  As to the rather light hindquarters, I''m torn as to whether it really helps the image; if that''s not a result of aesthetic processing choice, then please excuse my presumptuousness.  It certainly helps in bringing it forward, distinguished from the brush.  The delicacy and empathy here are remarkable.My personal favorite in the challenge.', '2017-09-06 16:27:07.000000', NULL, 1),
(7533490, 1204575, 173844, '<td valign="top">Beautiful color tones swaddled in atmosphere, a thin fog, perhaps.  It''s a dreamy, primaeval image.  The arrived, arriving and distant pelicans are quite picturesque.  (As an aside, I looked up what a group of pelicans are called and discovered pod, pouch, scoop and squadron.)  A gentle, arresting scene.  Terrific.</td>', 'Beautiful color tones swaddled in atmosphere, a thin fog, perhaps.  It''s a dreamy, primaeval image.  The arrived, arriving and distant pelicans are quite picturesque.  (As an aside, I looked up what a group of pelicans are called and discovered pod, pouch, scoop and squadron.)  A gentle, arresting scene.  Terrific.', '2017-09-06 16:43:12.000000', NULL, 1),
(7533492, 1204310, 173844, '<td valign="top">Dramatic and colorful.  The tree silhouette is bold and commanding.  I like how you''ve halved the scene, giving over the bottom half to what looks like a rice paddy, though I''m kind of guessing.  It seems like a generous decision that anchors the upper crescendo.  Strong image.</td>', 'Dramatic and colorful.  The tree silhouette is bold and commanding.  I like how you''ve halved the scene, giving over the bottom half to what looks like a rice paddy, though I''m kind of guessing.  It seems like a generous decision that anchors the upper crescendo.  Strong image.', '2017-09-06 16:48:33.000000', NULL, 1),
(7533494, 1204228, 173844, '<td valign="top">Intimate image wherein we''re invited under the spreading branches of this wonderful tree to watch the sunset/sunrise.  The title may refer to telling stories or stories without words, which seems to be the latter at the moment.  The tree also seems to be a curtain welcoming the dawn and closing the day.  A very evocative image.</td>', 'Intimate image wherein we''re invited under the spreading branches of this wonderful tree to watch the sunset/sunrise.  The title may refer to telling stories or stories without words, which seems to be the latter at the moment.  The tree also seems to be a curtain welcoming the dawn and closing the day.  A very evocative image.', '2017-09-06 16:59:21.000000', NULL, 1),
(7533496, 1204903, 173844, '<td valign="top">Fine foreground that perfectly establishes the receding land/seascape.  The highlighted surf and clouds nicely support each other.  Beautiful image.</td>', 'Fine foreground that perfectly establishes the receding land/seascape.  The highlighted surf and clouds nicely support each other.  Beautiful image.', '2017-09-06 17:09:27.000000', NULL, 1),
(7533498, 1204934, 173844, '<td valign="top">Straightforward, graphically striking image.  Wonderful how the ibis completes the diagonal, an elaborate exclamation point.  The balance and adroitness of the ibis are impressive.  Exciting nature photography.</td>', 'Straightforward, graphically striking image.  Wonderful how the ibis completes the diagonal, an elaborate exclamation point.  The balance and adroitness of the ibis are impressive.  Exciting nature photography.', '2017-09-06 17:27:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7533499, 1204857, 173844, '<td valign="top">Extraordinarily expressive, dynamic and delightful.  Here photography and imagination truly work hand in hand.  The color is modest and warm, as if the figure is emerging from amber.  Very fine.</td>', 'Extraordinarily expressive, dynamic and delightful.  Here photography and imagination truly work hand in hand.  The color is modest and warm, as if the figure is emerging from amber.  Very fine.', '2017-09-06 17:35:13.000000', NULL, 1),
(7533500, 1204800, 173844, '<td valign="top">Interesting composition that fits together like a puzzle.  The colors are appealing.  Reminiscent of Klee.  Nice.</td>', 'Interesting composition that fits together like a puzzle.  The colors are appealing.  Reminiscent of Klee.  Nice.', '2017-09-06 17:47:02.000000', NULL, 1),
(7533501, 1203791, 173844, '<td valign="top">Fine depiction of some amazing architecture.  Strong feeling of tradition and continuity.</td>', 'Fine depiction of some amazing architecture.  Strong feeling of tradition and continuity.', '2017-09-06 17:51:14.000000', NULL, 1),
(7533503, 1204609, 173844, '<td valign="top">Extraordinary close-up, creamy background.  Frightfully compelling.  Fine work.  This would make a great tattoo.</td>', 'Extraordinary close-up, creamy background.  Frightfully compelling.  Fine work.  This would make a great tattoo.', '2017-09-06 17:57:00.000000', NULL, 1),
(7533504, 1204904, 173844, '<td valign="top">Fine image of this pensive, pretty woman.  Great detail.  Understated yet powerful.  Exquisitely captured moment.</td>', 'Fine image of this pensive, pretty woman.  Great detail.  Understated yet powerful.  Exquisitely captured moment.', '2017-09-06 18:01:51.000000', NULL, 1),
(7533505, 1204859, 173844, '<td valign="top">Strong action image that beautifully captures the emotions and effort to be seen on the athletic field.  I initially thought that the background foliage were faces in the stands of a stadium, a pleasant confusion.</td>', 'Strong action image that beautifully captures the emotions and effort to be seen on the athletic field.  I initially thought that the background foliage were faces in the stands of a stadium, a pleasant confusion.', '2017-09-06 18:05:28.000000', NULL, 1),
(7533507, 1204663, 173844, '<td valign="top">Lovely, soulful portrait.  Nice purple tag.</td>', 'Lovely, soulful portrait.  Nice purple tag.', '2017-09-06 18:07:05.000000', NULL, 1),
(7533509, 1204783, 173844, '<td valign="top">Fine action shot.  The scooterer is somewhat swallowed by the background,  forcing the viewer to concentrate in order to pull him out, which is not at all a bad thing.  It creates dynamic tension. And the onlookers, like a Greek chorus.</td>', 'Fine action shot.  The scooterer is somewhat swallowed by the background,  forcing the viewer to concentrate in order to pull him out, which is not at all a bad thing.  It creates dynamic tension. And the onlookers, like a Greek chorus.', '2017-09-06 18:12:59.000000', NULL, 1),
(7533510, 1204943, 173844, '<td valign="top">Man, are they having fun, amidst beautifully shaded gray mist. The happy essence of childhood, handsomely photographed.</td>', 'Man, are they having fun, amidst beautifully shaded gray mist. The happy essence of childhood, handsomely photographed.', '2017-09-06 18:18:52.000000', NULL, 1),
(7533532, 1204310, 114285, '<td valign="top">Sure is one spectacular sunset, and the glorious hues cast in the water.  Don''t you wish you had a shot this for the one tree challenge.</td>', 'Sure is one spectacular sunset, and the glorious hues cast in the water.  Don''t you wish you had a shot this for the one tree challenge.', '2017-09-06 22:20:02.000000', NULL, 1),
(7533537, 1204575, 114285, '<td valign="top">Very ethereal looking image,  processing is spot on.  The added birds are always a bonus.</td>', 'Very ethereal looking image,  processing is spot on.  The added birds are always a bonus.', '2017-09-06 22:29:04.000000', NULL, 1),
(7533538, 1204666, 114285, '<td valign="top">It looks so casual, terrific shot.</td>', 'It looks so casual, terrific shot.', '2017-09-06 22:29:46.000000', NULL, 1),
